def emit(con,p,m,kind,suffix=''):
    msg=f"{p['retailer']}: {p['title']} a {p['price']:.2f} € · -{m['discount_pct']:.0f}% · Score {m['score']}{suffix}"
    try: con.execute("INSERT INTO alert_events(product_id,kind,title,message,price,discount_pct,score,created_at) VALUES(?,?,?,?,?,?,?,?)",(p['id'],kind,p['title'],msg,p['price'],m['discount_pct'],m['score'],now_iso()))
    except sqlite3.IntegrityError: pass

def watch_matches(con,p):
    for r in con.execute("SELECT * FROM alert_rules WHERE enabled=1"):
        if r['query'].lower() not in p['title'].lower(): continue
        if r['source_type']!='all' and r['source_type']!=p['source_type']: continue
        if r['region'] and p['source_type']=='market' and r['region']!=p['region']: continue
        if r['max_price'] is not None and p['price']>r['max_price']: continue
        return True
    return False

async def scan_once():
    con=connect(); st=settings_dict(con); n=0
    for d in DEMO:
        price=round(d['offer']*(1+random.uniform(-0.01,0.01)),2); p={**d,'price':price}
        con.execute("INSERT INTO products(id,title,brand,source_type,retailer,region,unit,url,image_url) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET title=excluded.title,brand=excluded.brand,source_type=excluded.source_type,retailer=excluded.retailer,region=excluded.region,unit=excluded.unit,url=excluded.url",(p['id'],p['title'],p['brand'],p['source_type'],p['retailer'],p['region'],p['unit'],p['url'],None))
        hist=[float(r['price']) for r in con.execute("SELECT price FROM prices WHERE product_id=? ORDER BY id DESC LIMIT 40",(p['id'],))]
        m=calc_metrics(hist,price,d['base']); con.execute("INSERT INTO prices(product_id,price,original_price,observed_at) VALUES(?,?,?,?)",(p['id'],price,d['base'],now_iso()))
        ok_source=st.get('source_filter','all') in ('all',p['source_type']); ok_region=p['source_type']!='market' or p['region']==st.get('region','Lombardia')
        if st.get('auto_enabled','1')=='1' and ok_source and ok_region and m['discount_pct']>=float(st.get('min_discount','45')) and m['score']>=int(st.get('min_score','85')): emit(con,p,m,'auto')
        if watch_matches(con,p): emit(con,p,m,'watchlist',' · watchlist')
        n+=1
    con.commit(); con.close(); return n

stop_event=asyncio.Event(); scanner_task=None
async def scanner_loop():
    while not stop_event.is_set():
        try: await scan_once()
        except Exception as e: print('scan error',e)
        con=connect(); seconds=int(settings_dict(con).get('scan_seconds','30')); con.close()
        try: await asyncio.wait_for(stop_event.wait(),timeout=seconds)
        except asyncio.TimeoutError: pass

@asynccontextmanager
async def lifespan(app:FastAPI):
    global scanner_task
    init_db(); await scan_once(); scanner_task=asyncio.create_task(scanner_loop()); yield; stop_event.set()
    if scanner_task: await scanner_task

app=FastAPI(title=APP_NAME,version=VERSION,lifespan=lifespan)
class SettingsIn(BaseModel):
    auto_enabled:bool=True; min_discount:int=45; min_score:int=85; scan_seconds:int=30; source_filter:str='all'; region:str='Lombardia'
class AlertRuleIn(BaseModel):
    query:str; max_price:float|None=None; source_type:str='all'; region:str|None=None; enabled:bool=True

@app.get('/',response_class=HTMLResponse)
def root(): return HTML
@app.get('/manifest.webmanifest')
def manifest(): return JSONResponse({'name':'Tairon Offerte - Sconti, prezzi e occasioni in tempo reale','short_name':'Tairon Offerte','start_url':'/','display':'standalone','background_color':'#f5f7fb','theme_color':'#ff3b4e'})
@app.get('/api/health')
def health():
    con=connect(); products=con.execute("SELECT COUNT(*) c FROM products").fetchone()['c']; events=con.execute("SELECT COUNT(*) c FROM alert_events").fetchone()['c']; con.close(); return {'ok':True,'version':VERSION,'products':products,'events':events,'time':now_iso()}
@app.get('/api/settings')
def get_settings():
    con=connect(); st=settings_dict(con); con.close(); return {'auto_enabled':st.get('auto_enabled','1')=='1','min_discount':int(st.get('min_discount','45')),'min_score':int(st.get('min_score','85')),'scan_seconds':int(st.get('scan_seconds','30')),'source_filter':st.get('source_filter','all'),'region':st.get('region','Lombardia')}
@app.put('/api/settings')
def put_settings(s:SettingsIn):
    vals={'auto_enabled':'1' if s.auto_enabled else '0','min_discount':str(s.min_discount),'min_score':str(s.min_score),'scan_seconds':str(s.scan_seconds),'source_filter':s.source_filter,'region':s.region}; con=connect()
    for k,v in vals.items(): con.execute("INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",(k,v))
    con.commit(); con.close(); return {'ok':True,**s.model_dump()}
@app.get('/api/deals')
def deals(region:str|None=None,source:str='all'):
    con=connect(); result=[]
    for p in con.execute("SELECT * FROM products ORDER BY retailer,title").fetchall():
        if source!='all' and p['source_type']!=source: continue
        if p['source_type']=='market' and region and p['region']!=region: continue
        latest=con.execute("SELECT * FROM prices WHERE product_id=? ORDER BY id DESC LIMIT 1",(p['id'],)).fetchone(); hist=[float(r['price']) for r in con.execute("SELECT price FROM prices WHERE product_id=? ORDER BY id DESC LIMIT 40",(p['id'],))]
        if latest: result.append({**dict(p),'price':latest['price'],'original_price':latest['original_price'],**calc_metrics(hist[1:],float(latest['price']),latest['original_price'])})
    con.close(); return result
@app.get('/api/watchlist')
def watchlist():
    con=connect(); rows=[dict(r) for r in con.execute("SELECT * FROM alert_rules ORDER BY id DESC")]; con.close(); return rows
@app.post('/api/watchlist')
def add_watchlist(r:AlertRuleIn):
    con=connect(); cur=con.execute("INSERT INTO alert_rules(query,max_price,source_type,region,enabled,created_at) VALUES(?,?,?,?,?,?)",(r.query,r.max_price,r.source_type,r.region,1 if r.enabled else 0,now_iso())); con.commit(); rid=cur.lastrowid; con.close(); return {'ok':True,'id':rid}
@app.delete('/api/watchlist/{rule_id}')
def del_watchlist(rule_id:int):
    con=connect(); cur=con.execute("DELETE FROM alert_rules WHERE id=?",(rule_id,)); con.commit(); found=cur.rowcount; con.close();
    if not found: raise HTTPException(404,'Rule not found')
    return {'ok':True}
@app.get('/api/alerts')
def alerts(limit:int=Query(50,ge=1,le=200),after:int=0):
    con=connect(); rows=[dict(r) for r in con.execute("SELECT * FROM alert_events WHERE id>? ORDER BY id DESC LIMIT ?",(after,limit))]; con.close(); return rows
@app.post('/api/scan/now')
async def scan_now(): return {'ok':True,'scanned':await scan_once(),'time':now_iso()}
@app.get('/api/events')
async def events():
    async def stream():
        last=0
        while True:
            con=connect(); rows=con.execute("SELECT * FROM alert_events WHERE id>? ORDER BY id",(last,)).fetchall(); con.close()
            for r in rows:
                last=r['id']; yield f"data: {json.dumps(dict(r),ensure_ascii=False)}\n\n"
            yield ': ping\n\n'; await asyncio.sleep(3)
    return StreamingResponse(stream(),media_type='text/event-stream')

